import * as React from "react";

import { useControllableState } from "../lib/use-controllable-state";
import { cn } from "../lib/utils";
import { Button } from "./button";
import {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandShortcut
} from "./command";
import { Icon, type IconName } from "./icon";
import { Kbd } from "./kbd";
import { Spinner } from "./spinner";

import menu from "./menu.module.css";
import styles from "./picker.module.css";

export type CommandMenuItem = {
  id: string;
  label: string;
  icon?: IconName;
  media?: React.ReactNode;
  description?: string;
  meta?: string;
  shortcut?: string;
  keywords?: string[];
  mono?: boolean;
  href?: string;
  onSelect?: () => void | Promise<void>;
  page?: string;
  disabled?: boolean;
  keepOpen?: boolean;
  danger?: boolean;
};
export type CommandMenuGroup = {
  label: string;
  items: readonly CommandMenuItem[];
  meta?: string;
  limit?: number;
  searchOnly?: boolean;
};
export type CommandMenuProps = {
  groups: readonly CommandMenuGroup[];
  recent?: readonly CommandMenuItem[];
  pages?: Record<
    string,
    { title: string; placeholder?: string; groups: readonly CommandMenuGroup[] }
  >;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  hotkey?: "mod+k" | false;
  onQueryChange?: (query: string, pageId?: string) => void;
  loading?: boolean;
  filter?: boolean;
  emptyHint?: string;
  footer?: React.ReactNode;
  inline?: boolean;
  label?: string;
};
export const CommandMenu = ({
  groups,
  recent = [],
  pages = {},
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  hotkey = "mod+k",
  onQueryChange,
  loading = false,
  filter = true,
  emptyHint,
  footer,
  inline = false,
  label = "Search workspace"
}: CommandMenuProps) => {
  const [open, setOpen] = useControllableState({
    value: controlledOpen,
    defaultValue: defaultOpen,
    onChange: onOpenChange
  });
  const [query, setQuery] = React.useState("");
  const [path, setPath] = React.useState<string[]>([]);
  const [active, setActive] = React.useState("");
  const [error, setError] = React.useState("");
  const epoch = React.useRef(0);
  const mounted = React.useRef(true);
  const inFlight = React.useRef(new Set<string>());
  const [pendingActions, setPendingActions] = React.useState<readonly string[]>([]);
  const previousOpen = React.useRef(open);
  const queryListener = React.useRef(onQueryChange);
  queryListener.current = onQueryChange;
  React.useLayoutEffect(() => {
    if (previousOpen.current !== open) epoch.current += 1;
    if (previousOpen.current && !open && !inline) {
      setPath([]);
      setQuery("");
      setActive("");
      setError("");
      queryListener.current?.("", undefined);
    }
    previousOpen.current = open;
  }, [inline, open]);
  React.useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      epoch.current += 1;
    };
  }, []);
  const pageId = path[path.length - 1];
  const page = pageId ? pages[pageId] : undefined;
  const updateQuery = (next: string) => {
    epoch.current += 1;
    setQuery(next);
    setError("");
    onQueryChange?.(next, pageId);
  };
  const back = () => {
    epoch.current += 1;
    setError("");
    setPath((previous) => previous.slice(0, -1));
    setQuery("");
    onQueryChange?.("", path[path.length - 2]);
  };
  React.useEffect(() => {
    if (!hotkey || inline) return;
    const listener = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.isComposing || event.repeat) return;
      if (
        (event.metaKey || event.ctrlKey) &&
        !event.altKey &&
        !event.shiftKey &&
        event.key.toLowerCase() === "k"
      ) {
        event.preventDefault();
        setOpen(!open);
      }
    };
    document.addEventListener("keydown", listener);
    return () => document.removeEventListener("keydown", listener);
  }, [hotkey, inline, open, setOpen]);
  const visibleGroups = page?.groups ?? groups;
  const allGroups =
    !page && !query && recent.length
      ? [{ label: "Recent", items: recent }, ...visibleGroups]
      : visibleGroups;
  const rank = (item: CommandMenuItem) => {
    const q = query.trim().toLowerCase();
    const text = item.label.toLowerCase();
    if (!q) return 1;
    if (text.startsWith(q)) return 4;
    if (text.split(/[\s_\-./:]+/).some((word) => word.startsWith(q))) return 3;
    if (text.includes(q)) return 2;
    return [item.description, ...(item.keywords ?? [])].some((value) =>
      value?.toLowerCase().includes(q)
    )
      ? 1
      : 0;
  };
  const selectedItem = allGroups.flatMap((group) => group.items).find((item) => item.id === active);
  const activate = async (item: CommandMenuItem) => {
    if (item.disabled || inFlight.current.has(item.id)) return;
    if (item.page) {
      const nextPage = item.page;
      if (!pages[nextPage]) {
        setError("This command page is unavailable.");
        return;
      }
      epoch.current += 1;
      setPath((previous) => [...previous, nextPage]);
      setQuery("");
      onQueryChange?.("", nextPage);
      return;
    }
    const turn = epoch.current;
    inFlight.current.add(item.id);
    setPendingActions([...inFlight.current]);
    setError("");
    try {
      await item.onSelect?.();
      if (turn !== epoch.current) return;
      if (item.href) window.location.assign(item.href);
      if (!item.keepOpen) setOpen(false);
    } catch (cause) {
      if (turn !== epoch.current || (cause instanceof DOMException && cause.name === "AbortError"))
        return;
      setError(`Could not ${item.label.toLowerCase()}. Try again.`);
    } finally {
      inFlight.current.delete(item.id);
      if (mounted.current) setPendingActions([...inFlight.current]);
    }
  };
  const markLabel = (text: string) => {
    const index = text.toLowerCase().indexOf(query.toLowerCase());
    return !query || index < 0 ? (
      text
    ) : (
      <>
        {text.slice(0, index)}
        <mark className={styles.match}>{text.slice(index, index + query.length)}</mark>
        {text.slice(index + query.length)}
      </>
    );
  };

  const panel = (
    <Command
      label={label}
      shouldFilter={false}
      loop
      value={active}
      onValueChange={setActive}
      onKeyDown={(event) => {
        if (event.nativeEvent.isComposing || event.keyCode === 229) return;
        if (inline && event.key === "Escape" && path.length) {
          event.preventDefault();
          event.stopPropagation();
          back();
        }
        if (event.key === "Backspace" && !query && path.length) {
          event.preventDefault();
          back();
        }
        if (event.key === "Enter" && (event.metaKey || event.ctrlKey) && selectedItem?.href) {
          event.preventDefault();
          if (selectedItem.disabled || inFlight.current.has(selectedItem.id)) return;
          window.open(selectedItem.href, "_blank", "noopener,noreferrer");
        }
      }}
    >
      <div className={styles.commandSearch}>
        {page && (
          <Button type="button" variant="ghost" size="icon-sm" aria-label="Back" onClick={back}>
            <Icon name="chev-left" />
          </Button>
        )}
        <CommandInput
          value={query}
          onValueChange={updateQuery}
          placeholder={page?.placeholder ?? label}
          aria-label={page?.title ?? label}
          onKeyDown={(event) => {
            if (event.nativeEvent.isComposing || event.keyCode === 229) event.stopPropagation();
          }}
          trailing={loading && <Spinner />}
        />
      </div>
      <CommandEmpty>
        <p role="status">
          {loading ? "Searching…" : `No results${query ? ` for "${query}"` : ""}`}
        </p>
        {emptyHint && <p>{emptyHint}</p>}
      </CommandEmpty>
      <CommandList>
        {allGroups
          .filter((group) => !group.searchOnly || query)
          .map((group) => {
            const items = group.items
              .map((item, index) => ({ item, score: rank(item), index }))
              .filter(({ score }) => !filter || score > 0)
              .sort((a, b) => (filter ? b.score - a.score || a.index - b.index : a.index - b.index))
              .slice(0, query && group.limit ? group.limit : undefined);
            return items.length ? (
              <CommandGroup key={group.label} heading={group.label}>
                {items.map(({ item }) => (
                  <CommandItem
                    key={item.id}
                    value={item.id}
                    disabled={item.disabled || pendingActions.includes(item.id)}
                    aria-busy={pendingActions.includes(item.id) || undefined}
                    data-danger={item.danger || undefined}
                    onSelect={() => {
                      activate(item);
                    }}
                  >
                    {item.media ? (
                      <span data-menu-icon="">{item.media}</span>
                    ) : (
                      item.icon && <Icon name={item.icon} />
                    )}
                    <span data-command-label className={menu.text}>
                      <span className={cn(menu.title, item.mono && styles.mono)}>
                        {markLabel(item.label)}
                      </span>
                      {item.description && (
                        <span className={menu.description}>{item.description}</span>
                      )}
                    </span>
                    {item.meta && <span className={menu.meta}>{item.meta}</span>}
                    {item.shortcut && <CommandShortcut>{item.shortcut}</CommandShortcut>}
                  </CommandItem>
                ))}
              </CommandGroup>
            ) : null;
          })}
      </CommandList>
      {error && (
        <p role="alert" className={styles.error}>
          {error}
        </p>
      )}
      <div className={menu.hints} data-slot="command-menu-hints">
        <span className={menu.hint}>
          <Kbd size="sm" keys={["up"]} />
          <Kbd size="sm" keys={["down"]} />
          Navigate
        </span>
        <span className={menu.hint}>
          <Kbd size="sm" keys="enter" />
          Open
        </span>
        <span className={menu.hint}>
          <Kbd size="sm" keys="esc" />
          {page ? "Back" : "Close"}
        </span>
        {footer && <span className={menu.hintsExtra}>{footer}</span>}
      </div>
    </Command>
  );
  return inline ? (
    panel
  ) : (
    <CommandDialog
      onEscapeKeyDown={(event) => {
        if (path.length) {
          event.preventDefault();
          back();
        }
      }}
      open={open}
      onOpenChange={setOpen}
      title={label}
      description="Search pages, objects and actions"
    >
      {panel}
    </CommandDialog>
  );
};

.surface {
  box-sizing: border-box;
  border-radius: calc(var(--v4-radius-pop) * var(--corners));
  background-color: var(--v4-pop);
  color: var(--v4-ink);
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-pop-line),
    var(--v4-shadow-pop);
  outline: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
.panel {
  min-width: min(
    max(var(--v4-size-menu-min), var(--radix-popper-anchor-width, 0px)),
    var(--radix-popper-available-width, 100vw)
  );
  max-width: min(
    var(--v4-size-menu-max),
    var(--radix-popper-available-width, calc(100vw - 2 * var(--v4-space-16)))
  );
  max-height: var(--radix-popper-available-height, none);
  overflow-x: hidden;
  overflow-y: auto;
}
.sub {
  min-width: var(--v4-size-menu-min);
}
.card {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-8);
  width: min(var(--v4-size-popover), var(--radix-popper-available-width, 100vw));
  max-height: var(--radix-popper-available-height, none);
  overflow-y: auto;
  padding: var(--v4-space-12);
}
.tooltip {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-8);
  width: fit-content;
  max-width: min(var(--v4-size-menu-max), var(--radix-popper-available-width, 100vw));
  padding: var(--v4-space-6) var(--v4-space-8);
  border-radius: calc(var(--v4-radius-sm) * var(--corners));
  background-color: var(--v4-ink);
  color: var(--v4-on-ink);
  box-shadow: var(--v4-shadow-pop);
  overflow-wrap: break-word;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.tooltip:has([data-slot="kbd"]) {
  padding-inline-end: var(--v4-space-6);
}
.tooltipArrow {
  fill: var(--v4-ink);
}

.motion {
  --v4-pop-from: 0 0;
  transform-origin: var(--radix-popper-transform-origin, center);
}
.motion[data-side="bottom"] {
  --v4-pop-from: 0 calc(-1 * var(--v4-space-4));
}
.motion[data-side="top"] {
  --v4-pop-from: 0 var(--v4-space-4);
}
.motion[data-side="right"] {
  --v4-pop-from: calc(-1 * var(--v4-space-4)) 0;
}
.motion[data-side="left"] {
  --v4-pop-from: var(--v4-space-4) 0;
}
.motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]) {
  animation: popIn var(--v4-duration-fast) var(--v4-ease-spring) both;
}
.motion[data-state="closed"] {
  animation: popOut var(--v4-duration-exit-fast) var(--v4-ease-exit) both;
}
.tooltip.motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]) {
  animation-name: tipIn;
}
.tooltip.motion[data-state="closed"] {
  animation-name: tipOut;
}
@keyframes popIn {
  from {
    opacity: 0;
    translate: var(--v4-pop-from);
    scale: 1 0.96;
  }
}
@keyframes popOut {
  to {
    opacity: 0;
    translate: var(--v4-pop-from);
    scale: 1 0.96;
  }
}
@keyframes tipIn {
  from {
    opacity: 0;
    translate: var(--v4-pop-from);
  }
}
@keyframes tipOut {
  to {
    opacity: 0;
    translate: var(--v4-pop-from);
  }
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]),
  .tooltip.motion:is(
      [data-state="open"],
      [data-state="delayed-open"],
      [data-state="instant-open"]
    ) {
    animation-name: fadeIn;
  }
  .motion[data-state="closed"],
  .tooltip.motion[data-state="closed"] {
    animation-name: fadeOut;
  }
}

.inset {
  --v4-menu-icon-slot: 0px;
  padding: var(--v4-space-4);
}
.inset:has(.row > :is(svg, [data-menu-icon]):not(.trail), .row[data-inset], .label[data-inset]) {
  --v4-menu-icon-slot: calc(var(--v4-size-icon) + var(--v4-space-8));
}

.list {
  max-height: calc(9 * var(--v4-size-control-sm));
  overflow-x: hidden;
  overflow-y: auto;
  outline: none;
  scroll-padding-block: var(--v4-space-4);
}

.row {
  position: relative;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  min-width: 0;
  min-height: var(--v4-size-control-sm);
  padding: var(--v4-space-6) var(--v4-space-8);
  padding-inline-start: calc(var(--v4-space-8) + var(--v4-menu-icon-slot, 0px));
  border-radius: calc(var(--v4-radius-sm) * var(--corners));
  overflow: hidden;
  color: var(--v4-ink);
  white-space: nowrap;
  cursor: default;
  user-select: none;
  outline: none;
  text-decoration: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
.row:has(> :is(svg, [data-menu-icon]):not(.trail)) {
  padding-inline-start: var(--v4-space-8);
}
.row > svg,
.row > [data-menu-icon] {
  flex: none;
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  pointer-events: none;
}
.row:is(
    [data-highlighted],
    [data-selected="true"],
    [data-active],
    [data-state="open"],
    a:hover,
    a:focus-visible
  ) {
  background-color: var(--v4-select);
}
.row:is([data-variant="destructive"], [data-danger]) {
  color: var(--v4-bad);
}
.row:is([data-variant="destructive"], [data-danger]):is(
    [data-highlighted],
    [data-selected="true"]
  ) {
  background-color: var(--v4-action-danger-surface);
}
.row:is([data-disabled]:not([data-disabled="false"]), [aria-disabled="true"]) {
  color: var(--v4-faint);
  background-color: transparent;
  pointer-events: none;
}
.indicator {
  order: 1;
  display: flex;
  flex: none;
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  align-items: center;
  justify-content: center;
  margin-inline-start: auto;
  pointer-events: none;
}
.indicator > svg {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.indicator ~ :is(.shortcut, .meta) {
  margin-inline-start: 0;
}
.row:not([data-checked="true"]) > .indicator[data-command] {
  visibility: hidden;
}
.text {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
}
.title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.description {
  min-width: 0;
  overflow: hidden;
  color: var(--v4-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.shortcut,
.meta {
  order: 2;
  margin-inline-start: auto;
  padding-inline-start: var(--v4-space-8);
  color: var(--v4-muted);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.shortcut {
  display: inline-flex;
  flex: none;
  align-items: center;
}
.meta {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 45%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.meta + .shortcut {
  margin-inline-start: 0;
}
.trail {
  order: 3;
  flex: none;
  margin-inline-start: auto;
  color: var(--v4-muted);
}
.label,
.group > [cmdk-group-heading] {
  display: block;
  padding: var(--v4-space-6) var(--v4-space-8);
  padding-inline-start: calc(var(--v4-space-8) + var(--v4-menu-icon-slot, 0px));
  color: var(--v4-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.label:not(:first-child, .separator + *),
:is([role="group"], [cmdk-group]):not(:first-child)
  > :is(.label, [cmdk-group-heading]):first-child {
  margin-top: var(--v4-space-4);
  padding-top: calc(var(--v4-space-6) + var(--v4-space-4));
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.separator {
  height: var(--v4-size-control-border);
  margin: var(--v4-space-4) 0;
  border: 0;
  background-color: var(--v4-line-soft);
}
.empty {
  padding: var(--v4-space-16) var(--v4-space-8);
  color: var(--v4-muted);
  text-align: center;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--v4-space-4);
  padding: var(--v4-space-4);
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.hints {
  container-type: inline-size;
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  min-height: var(--v4-size-control-sm);
  padding: var(--v4-space-4) var(--v4-space-12);
  overflow: hidden;
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.hint {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-4);
}
.hintsExtra {
  min-width: 0;
  margin-inline-start: auto;
  overflow: hidden;
  text-overflow: ellipsis;
}
@container (max-width: 360px) {
  .hint:nth-child(n + 2) {
    display: none;
  }
}
@container (max-width: 200px) {
  .hint {
    display: none;
  }
}

.navItem {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--v4-space-control-gap);
  box-sizing: border-box;
  min-height: var(--v4-size-control-sm);
  padding: var(--v4-space-6) var(--v4-space-control-inline-sm);
  border-radius: calc(var(--v4-radius-control) * var(--corners));
  background-color: transparent;
  color: var(--v4-ink);
  white-space: nowrap;
  text-decoration: none;
  transition-property: background-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
  font-family: var(--v4-type-label-font-family);
  font-size: var(--v4-type-label-font-size);
  line-height: var(--v4-type-label-line-height);
  font-weight: var(--v4-type-label-font-weight);
  letter-spacing: var(--v4-type-label-letter-spacing);
}
.navItem:is(:hover, [data-state="open"], [data-active]) {
  background-color: var(--v4-select);
}
.navItem:disabled {
  opacity: 0.5;
  pointer-events: none;
}
.navChevron {
  width: var(--v4-size-icon-xs);
  height: var(--v4-size-icon-xs);
  transition-property: rotate;
  transition-duration: var(--v4-duration-moderate);
  transition-timing-function: var(--v4-ease-standard);
}
.navItem[data-state="open"] > .navChevron {
  rotate: 180deg;
}
.navViewportAnchor {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 50;
  display: flex;
  padding-top: var(--v4-space-4);
  translate: var(--v4-nav-viewport-x, 0) 0;
}
.navViewportAnchor[data-placed] {
  transition-property: translate;
  transition-duration: var(--v4-duration-moderate);
  transition-timing-function: var(--v4-ease-standard);
}
.navViewport {
  position: relative;
  overflow: hidden;
  width: var(--radix-navigation-menu-viewport-width);
  height: var(--radix-navigation-menu-viewport-height);
  max-width: min(calc(100vw - 2 * var(--v4-space-16)), var(--v4-size-measure-form));
  transform-origin: top left;
}
.navContent {
  position: absolute;
  top: 0;
  left: 0;
  box-sizing: border-box;
  width: max-content;
  min-width: var(--v4-size-menu-min);
  max-width: min(calc(100vw - 2 * var(--v4-space-16)), var(--v4-size-measure-form));
}
@media (prefers-reduced-motion: reduce) {
  .navViewportAnchor[data-placed],
  .navChevron {
    transition: none;
  }
}

.mono {
  font-family: var(--v4-font-mono, monospace);
}
.error {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-bad, var(--destructive));
  padding: var(--v4-space-8) var(--v4-space-12);
}
.chips {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--v4-space-4);
}
.commandSearch {
  display: flex;
  align-items: center;
  gap: var(--v4-space-4);
  padding-inline-end: var(--v4-space-menu-inset);
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.commandSearch:focus-within {
  border-bottom-color: var(--v4-control);
}
.commandSearch > [data-slot="command-input-wrapper"] {
  flex: 1;
  min-width: 0;
  border-bottom: 0;
}
.commandSearch > [data-v4-button] + [data-slot="command-input-wrapper"] {
  padding-inline-start: 0;
}
.commandSearch > [data-v4-button]:first-child {
  margin-inline-start: var(--v4-space-menu-inset);
}
.multiCombobox > [data-slot="multi-select"] {
  flex: 1 1 120px;
  width: auto;
}
.multiCombobox
  > [data-slot="multi-select"]:is(*, :focus-visible, [aria-expanded], [aria-invalid])[data-slot] {
  min-height: var(--v4-field-nested);
  padding-block: 0;
  padding-inline-start: calc(var(--v4-field-inline) - var(--v4-space-control-slot-inset));
  border: 0;
  background: transparent;
  box-shadow: none;
}
.match {
  background: var(--v4-accent);
  color: var(--v4-on-accent);
}

.triggerValue {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.triggerValue[data-placeholder] {
  color: var(--v4-muted);
}
.summary {
  display: flex;
  align-items: center;
  gap: var(--v4-space-6);
  min-width: 0;
}
.summary > span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.more {
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-mono-sm-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  letter-spacing: var(--v4-type-mono-sm-letter-spacing);
  flex: 0 0 auto;
  color: var(--v4-muted);
}

.chip {
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: var(--v4-type-caption-font-weight);
  letter-spacing: var(--v4-type-caption-letter-spacing);
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-4);
  border: 1px solid var(--v4-line-soft, var(--border));
  padding: 2px 6px;
  min-width: 0;
  max-width: 100%;
  border-radius: calc(var(--v4-radius-control) * var(--corners));
}
.chip > span:first-child {
  min-width: 0;
  overflow-wrap: anywhere;
}
.chip > [data-v4-button] {
  flex-shrink: 0;
}
.multiCombobox[data-size] {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--v4-space-control-slot-gap);
  padding-block: var(--v4-space-control-slot-inset);
  padding-inline: var(--v4-space-control-slot-inset) 0;
}
.multiCombobox > .chip {
  box-sizing: border-box;
  height: var(--v4-field-nested);
  padding-block: 0;
  padding-inline: calc(
      var(--v4-field-inline) - var(--v4-space-control-slot-inset) - var(--v4-size-control-border)
    )
    0;
}
.multiCombobox > .chip > [data-v4-button] {
  --v4-action-height: calc(var(--v4-field-nested) - 2 * var(--v4-size-control-border));
}
